    @field_validator('minimum_grade', mode='before')
    @classmethod
    def normalize_minimum_grade(cls, value):
        if value is None:
            return None
        if isinstance(value, str):
            stripped = value.strip()
            return stripped.upper() if stripped else None
        return value

